using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so keep the old property name.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 uses only the raw key for "id" (e.g. "1").
            // Existing documents store "id" as "Blog|1", so preserve that format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via
            // EF Core; HasIndex() now throws at model validation time in EF 9.
            // Removed the HasIndex call — use Azure Portal to manage Cosmos indexes.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Breaking change 4: EF 9 uses "sync" semantics differently — patch-based
    // updates send only changed properties. Ensure __etag is mapped so optimistic
    // concurrency still works on existing documents.
}

/// <summary>
/// Generates ids in the legacy "Blog|{key}" format so new documents
/// match the format already stored in Cosmos DB.
/// </summary>
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

