class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 5: Raw SQL must reference "$type" instead of
        // "Discriminator" — unless HasJsonPropertyName was configured (we did).
        // If you have any raw queries elsewhere, update them accordingly:
        //   Before: SELECT * FROM c WHERE c.Discriminator = 'Blog'
        //   After (without config): SELECT * FROM c WHERE c["$type"] = 'Blog'
        //   With our config fix above, the old query still works.

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

